// A plugin package as an app installs it. It cannot import the workspace's TypeScript, so it carries the brand
// `defineLintPlugin` puts on its result: the plugin API version under a registry symbol, so a package with its
// own copy is still recognised.
const rules = Object.freeze([
  Object.freeze({
    name: "served-at",
    defaultSeverity: "warning",
    reports: "a body without servedAt",
    silencedOn: "the route",
    check() {},
  }),
]);

export default Object.freeze({
  name: "acme",
  rules,
  [Symbol.for("seampact.lint.definedPlugin")]: 1,
});
